export declare const workbenchStyles = "\n.storyStudioWorkbenchRoot {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n  width: 100%;\n  background: var(--dsw-alias-bg-base);\n  color: var(--dsw-alias-text-primary);\n}\n\n.storyStudioWorkbenchLayout {\n  display: grid;\n  grid-template-columns: 240px 1fr 320px;\n  height: 100%;\n  overflow: hidden;\n}\n\n.storyStudioWorkbenchSidebar {\n  border-right: 1px solid var(--dsw-alias-border-l1);\n  background: var(--dsw-alias-bg-layer-1);\n  overflow-y: auto;\n}\n\n.storyStudioWorkbenchMain {\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n}\n\n.storyStudioWorkbenchPanel {\n  border-left: 1px solid var(--dsw-alias-border-l1);\n  background: var(--dsw-alias-bg-layer-1);\n  overflow-y: auto;\n}\n\n.storyStudioFileTree {\n  padding: 8px;\n}\n\n.storyStudioFileTreeItem {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 4px 8px;\n  border-radius: 6px;\n  cursor: pointer;\n  font-size: 13px;\n  user-select: none;\n}\n\n.storyStudioFileTreeItem:hover {\n  background: var(--dsw-alias-fill-hover);\n}\n\n.storyStudioFileTreeItem[data-selected=\"true\"] {\n  background: var(--dsw-alias-fill-selected);\n}\n\n.storyStudioFileTreeIcon {\n  flex: none;\n  width: 16px;\n  height: 16px;\n  color: var(--dsw-alias-text-secondary);\n}\n\n.storyStudioFileTreeName {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.storyStudioEditorTabs {\n  display: flex;\n  gap: 2px;\n  padding: 8px 8px 0;\n  background: var(--dsw-alias-bg-layer-1);\n  border-bottom: 1px solid var(--dsw-alias-border-l1);\n  overflow-x: auto;\n}\n\n.storyStudioEditorTab {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  height: 32px;\n  padding: 0 12px;\n  border-radius: 6px 6px 0 0;\n  background: transparent;\n  border: 0;\n  cursor: pointer;\n  font-size: 13px;\n  color: var(--dsw-alias-text-secondary);\n  white-space: nowrap;\n}\n\n.storyStudioEditorTab:hover {\n  background: var(--dsw-alias-fill-hover);\n}\n\n.storyStudioEditorTab[data-active=\"true\"] {\n  background: var(--dsw-alias-bg-base);\n  color: var(--dsw-alias-text-primary);\n}\n\n.storyStudioEditorTabName {\n  max-width: 120px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.storyStudioEditorTabClose {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 16px;\n  height: 16px;\n  border-radius: 3px;\n  border: 0;\n  background: transparent;\n  color: currentColor;\n  cursor: pointer;\n  padding: 0;\n}\n\n.storyStudioEditorTabClose:hover {\n  background: var(--dsw-alias-fill-hover);\n}\n\n.storyStudioEditorContent {\n  flex: 1;\n  overflow: auto;\n  padding: 16px;\n  font-family: 'SF Mono', Monaco, 'Cascadia Code', 'Roboto Mono', Consolas, 'Courier New', monospace;\n  font-size: 13px;\n  line-height: 1.6;\n  white-space: pre-wrap;\n  word-break: break-word;\n}\n\n.storyStudioEditorTextarea {\n  width: 100%;\n  height: 100%;\n  border: 0;\n  background: transparent;\n  color: inherit;\n  font: inherit;\n  resize: none;\n  outline: none;\n}\n\n.storyStudioPreviewPanel {\n  padding: 16px;\n}\n\n.storyStudioPreviewContent {\n  font-size: 14px;\n  line-height: 1.8;\n}\n\n.storyStudioPreviewContent h1,\n.storyStudioPreviewContent h2,\n.storyStudioPreviewContent h3 {\n  margin: 1.5em 0 0.5em;\n  font-weight: 600;\n}\n\n.storyStudioPreviewContent h1 { font-size: 1.8em; }\n.storyStudioPreviewContent h2 { font-size: 1.5em; }\n.storyStudioPreviewContent h3 { font-size: 1.2em; }\n\n.storyStudioPreviewContent p {\n  margin: 0.8em 0;\n}\n\n.storyStudioPreviewContent code {\n  padding: 2px 6px;\n  border-radius: 4px;\n  background: var(--dsw-alias-bg-layer-2);\n  font-family: inherit;\n  font-size: 0.9em;\n}\n\n.storyStudioPreviewContent pre {\n  padding: 12px;\n  border-radius: 6px;\n  background: var(--dsw-alias-bg-layer-2);\n  overflow-x: auto;\n}\n\n.storyStudioPreviewContent pre code {\n  padding: 0;\n  background: transparent;\n}\n";
